using Avalonia.Controls;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop; public sealed partial class ManagerBillingWindow : Window { private readonly IBillingManager manager; private readonly Guid organizationId; public ManagerBillingWindow() => throw new InvalidOperationException("Billing runtime is required."); public ManagerBillingWindow(IBillingManager manager, Guid organizationId) { this.manager = manager ?? throw new ArgumentNullException(nameof(manager)); if (organizationId == Guid.Empty) throw new ArgumentException("Organization is required."); this.organizationId = organizationId; InitializeComponent(); ScopeText.Text = $"Organization {organizationId:D}"; } private async void CreateAccountClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(async () => { var a = await manager.CreateAccountAsync(organizationId, LegalNameBox.Text ?? "", EmailBox.Text ?? "", (CurrencyBox.Text ?? "").Trim().ToUpperInvariant(), Guid.NewGuid(), Guid.NewGuid(), default); AccountText.Text = $"{a.LegalName} · {a.AccountId:D} · {a.Currency}"; }); private async void LoadInvoiceClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(async () => { var v = await manager.GetInvoiceAsync(organizationId, Guid.Parse(InvoiceBox.Text ?? ""), default); InvoiceText.Text = $"{v.Number} · {v.Status}\nGross {v.GrossAmount:0.00} {v.Currency} · Paid {v.PaidAmount:0.00} · Balance {v.Balance:0.00}\nDue {v.DueAt:u}"; }); private async Task Execute(Func<Task> a) { try { await a(); MessageText.Text = ""; } catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or HttpRequestException or FormatException) { MessageText.Text = ex is HttpRequestException ? "Billing service request failed." : ex.Message; } } }
